! Lúc này làm lễ xưng Vương e không được nhân hòa." }, new string[] { "06", "Tại sao? Quân sư, xin hãy nói." }, new string[] { "08", "Loạn sơn tặc Tam Điệp khiến người dân quanh vùng khiếp sợ, sống không yên." }, new string[] { "08", "Chủ tướng nên cho người đến bình loạn trước, sau xưng Vương thì được lòng dân trong vùng hơn." }, new string[] { "06", "Quân sư nói phải lắm!" }, new string[] { "07", "Chủ tướng! Hãy để tôi dẹp loạn sơn tặc." }, new string[] { "08", "Tướng quân, ngài phải giúp tôi chuẩn bị cho đại lễ. Việc dẹp sơn tặc xin nhờ {p} tướng quân." }, new string[] { "06", "Nếu quân sư đã có sắp xếp rồi thì ta cũng nên theo. {p} tướng quân hãy thận trọng!" }, new string[] { "00", "Mạt tướng tuân lệnh!" } }, new string[][] { new string[] { "42", "Quân Hoa Lư chỉ có bấy nhiêu thôi ư? Chúng xem thường ta quá đấy!." }, new string[] { "42", "Tấn công! Giết hết bọn rác rưởi cho ta." }, new string[] { "00", "Tiến lên, tiêu diệt bọn đạo tặc! " } }, new string[][] { new string[] { "08", "Chủ tướng, giờ lành đã đến. Chúng ta mau tiến hành đại lễ cho kịp." }, new string[] { "06", "Thiên hạ đại nghĩa, Ngô vương chẳng may mất sớm, loạn thần mải tranh giành vương bá, không lo thiên hạ, để đất nước loạn lạc, chiến tranh liên miên, dân chúng lầm than. Nay thuận thiên ý, Bộ Lĩnh họp quân dẹp loạn, quyết thu giang sơn về một mối. Kẻ nào không phục, thì Vạn Thắng Vương này tiêu diệt không tha!" }, new string[] { null, "Vạn Thắng Vương vạn tuế! Vạn tuế!" }, new string[] { "06", "Chư tướng, hãy đứng lên!" }, new string[] { "06", "Trận đầu, ta muốn đánh một trận thật lừng lẫy để các nơi phải khiếp sợ. Lưu Cơ, ta nên đánh ai trước? " }, new string[] { "08", "Thưa đại vương, 12 sứ quân đáng gờm nhất là Phạm Bạch Hổ. Ông ta vốn làm tướng dưới thời Ngô Vương lại là người có uy đức. Quân sĩ được huấn luyện rất bài bản, quân thủy bộ uy dũng. Đánh Phạm Bạch Hổ nếu thắng thì uy phong rất lớn, nếu thua quân ta sẽ mất nhuệ khí mà các sứ quân khác cũng xem thường." }, new string[] { "07", "Tập trung toàn quân, đánh một trận quyết tử. Thắng được Phạm Bạch Hổ xem như ta có nửa giang sơn. Sợ gì !" }, new string[] { "08", "Không được! Kế đó là “Được ăn cả ngã về không”. Tốt nhất là ta cứ theo binh pháp cơ bản, đánh kẻ yếu hòa kẻ mạnh, xưa nay vẫn thế. Ta nên hòa với Phạm Bạch Hổ." }, new string[] { "06", "Vậy ai sẽ là người đi sang thuyết khách đây?" }, new string[] { "08", "Nhiệm vụ thuyết khách, xin để Lưu Cơ!" }, new string[] { "06", "Chuyến đi lành ít dữ nhiều, tướng quân {p} hãy đi cùng quân sư. Hai vị hãy cẩn trọng." }, new string[] { "00", "Mạt tướng tuân lệnh!" } }, new string[][] { new string[] { "08", "Lưu Cơ ở Hoa Lư, xin bái kiến Phạm sứ quân!!" }, new string[] { "18", "Lưu tiên sinh, mời an tọa! " }, new string[] { "18", "Chẳng hay Lưu quân sư đến xứ Đằng Châu có việc gì?" }, new string[] { "08", "Chủ tướng tôi có thư này gửi Phạm sứ quân, xin sứ quân xem qua." }, new string[] { "18", "Hãy đưa thư cho ta..........." }, new string[] { "18", "Thư ta đã đọc, chuyện an hòa nghe cũng thuận lòng. Nhưng còn phải xem ý trời ra sao?" }, new string[] { "18", "Nghe nói tiên sinh tinh thông Kỳ môn độn giáp. Ông hãy xem ý trời giúp tôi." }, new string[] { "08", "Mời sứ quân gieo quẻ!" }, new string[] { "08", "Quẻ của tướng quân là quẻ Thủy Địa Tỷ. Lời quẻ nói rằng “Lục nhị: tỷ chi tử nội, trinh cát”. Xin dịch nghĩa như sau: “ Hai bên thân nhau vì đạo đồng chí hợp, chứ không phải vì kết thân với bề trên để cầu phú quí, như vậy là chính đáng, không thất thân, nên tốt. ”" }, new string[] { "18", "Ý trời đã vậy, Bạch Hổ không dám trái thiên ý. " }, new string[] { "18", "Quân sư hãy mang hòa ước này về Hoa Lư. Từ nay, chúng ta hiếu hòa, không xâm lấn, không gây phiền hà cho nhau, ai giàu nấy hưởng, ai mạnh tự cường, tình hữu hảo láng giềng, trước sau như một. Nếu có kẻ đánh Hoa Lư, Phạm Bạch Hổ sẵn lòng giúp đỡ." }, new string[] { "08", "Lưu Cơ thay mặt Vạn Thắng Vương vô cùng cảm kích Phạm sứ quân!" } }, new string[][] { new string[] { "06", "Ta đã hòa với Phạm Bạch Hổ, vậy gần Hoa Lư nhất chỉ còn Ngô Xương Xí ở Bình Kiều." }, new string[] { "07", "Con thỏ non trốn chạy về miền rừng núi âm u ấy, đáng kể gì!  " }, new string[] { "08", "Nhưng cũng không thể chủ quan, nếu lấy được Bình Kiều thì sẽ an tâm hơn khi tiến quân lên phía bắc." }, new string[] { "06", "Xương Xí thân là cháu Ngô Vương, diệt hắn thì thiên hạ sẽ có nhiều lời không hay. Ta nên chiêu hàng hắn, Nguyễn Bặc ở Hoa Lư phòng thủ. Những người còn lại theo ta." }, new string[] { "00", "Tuân lệnh Đại Vương." } }, new string[][] { new string[] { "00", "Ngô Xương Xí! Bình Kiều đã bị bao vây, khôn ngoan hãy mau ra hàng." }, new string[] { "22", "Có thực lực thì đến đây, đừng nhiều lời." } }, new string[][] { new string[] { "06", "Trước mặt ta có Đỗ Cảnh Thạc và Ngô Nhật Khánh. Quân sư, chúng ta nên đánh ai trước." }, new string[] { "08", "Đỗ Cảnh Thạc là lão tướng dày dặn kinh nghiệm, có thành trì chắc chắn và hào sâu bao quanh, nếu đánh trước chắn chắn lực lượng sẽ hao tổn rất nhiều. Ngô Nhật Khánh thì ở rất xa, chỉ có một đường duy nhất đến đó lại gập ghềnh nguy hiểm. Quân ta đến nơi thì cũng rất mệt mỏi, sức đâu mà đánh trận." }, new string[] { "07", "Gần không đánh được, Xa cũng không được đánh. Vậy ta ở đây làm gì ?!" }, new string[] { "06", "Haha, tướng quân! Hãy để quân sư nói tiếp xem sao." }, new string[] { "08", "Tướng quân, hãy bình tĩnh. Đánh ai trước, ta cũng phải bàn tính kỹ càng." }, new string[] { "08", "Thưa Đại Vương, trong 2 sứ quân thì Ngô Nhật Khánh là yếu nhất, tuy thông minh nhưng còn rất trẻ, ít trải nghiệm và rất bốc đồng. Đánh Khánh trước là thích hợp nhất mà khả năng hao tổn lực lượng ít hơn so với những người khác. Nhưng ta cũng phải đề phòng Đỗ Cảnh Thạc đánh từ phía sau lại. " }, new string[] { "08", "Tôi có ý này. Đem quân giả đánh Cảnh Thạc, đến Ô Man chia quân làm 3 đạo. Đạo thứ nhất do tướng Nguyễn Bặc chỉ huy đóng ở Ô Man, đạo thứ 2 do Đại vương chỉ huy đóng trực diện với đồn Bảo Đà. Đạo thứ 3 sẽ do tướng {p} dẫn đầu, bí mật đi đến Đường Lâm bất ngờ đến đánh Ngô Nhật Khánh chắc chắn hắn sẽ trơ tay không kịp." }, new string[] { "06", "Tốt! Mọi người hãy y theo mà hành động." }, new string[] { "00", "Tuân lệnh Đại Vương" } }, new string[][] { new string[] { "27", "Bọn ngươi là quân của ai, muốn chết hay sao mà đám đến đây làm loạn?" }, new string[] { "00", "Ta là {p}, tướng tiên phong của Vạn Thắng Vương, hôm nay ta đến lấy đầu ngươi!" }, new string[] { "27", "Láo xược! Ta sẽ phân thây ngươi để làm gương cho kẻ khác." } }, new string[][] { new string[] { "08", "Lã Đường ở Tế Giang đã cất binh đánh Phạm Bạch Hổ. Ta đã có hòa ước với Bạch Hổ, nên không thể không giúp, hơn nữa nếu Đằng Châu mất thì Kỳ Bố cũng sẽ khó mà yên. Đại Vương và tướng Nguyễn Bặc đang giữ chân Cảnh Thạc không thể đem quân tiếp ứng. Thời gian cấp bách, tướng quân hãy đem quân ứng cứu trước, tôi sẽ theo sau. Trong 5 ngày chúng ta phải đến đó, nếu không thì Đằng Châu khó mà giữ được." }, new string[] { "00", "Lưu quân sư yên tâm, mạt tướng sẽ đi ngay!" } }, new string[][] { new string[] { "00", "Phạm sứ quân! Có tôi đến trợ giúp đây." }, new string[] { "20", "Hừ, quân giặc có viện binh, không xong rồi!" }, new string[] { "00", "Lão ác tặc, hãy xem đây!" } }, new string[][] { new string[] { "18", "Đa tạ tướng quân giúp đỡ." }, new string[] { "00", "Chúng ta là người một nhà, Phạm sứ quân xin đừng khách sáo." }, new string[] { "08", "Sau trận vừa rồi binh lực của Lã Đường đã suy yếu, nhuệ khí không còn. Hơn nữa quân ta lại đông hơn, hào khí ngất trời. Nhân cơ hội này, tiến quân đánh vào Tế Giang chắc chắn sẽ hạ được." }, new string[] { "18", "Lưu quân sư nói phải lắm. Mọi người nghỉ ngơi lấy sức, sớm mai xuất quân." }, new string[] { "08", "Lưu Cơ xin cáo lui." }, new string[] { "00", "{p} xin cáo lui." } }, null, new string[][] { new string[] { "00", "Lã Đường, ta đến lấy đầu ngươi đây!" }, new string[] { "20", "Với sức ngươi ư? Ảo tưởng ! Sáttttt" } }, new string[][] { new string[] { "08", "Phạm sứ quân, Tế Giang đã diệt xong. Chúng tôi phải trở về, Lưu Cơ xin bái biệt!" }, new string[] { "18", "Lưu quân sư, Vạn Thắng Vương là người nhân nghĩa lại có chí lớn bình định thiên hạ, đúng là phước của muôn dân. Nếu Bạch Hổ được giúp một tay thì thật là vinh hạnh lắm lắm!" }, new string[] { "08", "Lưu Cơ sẽ chuyển tâm ý của Phạm sứ quân đến Vạn Thắng Vương. " }, new string[] { "18", "Đa tạ quân sư!" }, new string[] { "08", "Nhất định sẽ có ngày chúng ta gặp lại. Phạm sứ quân, hẹn ngày tái ngộ!" }, new string[] { "18", "Lưu quân sư, hãy bảo trọng!" } }, new string[][] { new string[] { "06", "Quân sư, ông đến thật đúng lúc, quân địch phòng thủ rất chặt, ta khó mà đánh vào được." }, new string[] { "08", "Đại vương yên tâm, cơ hội của chúng ta đã đến. Đỗ Cảnh Thạc đang ở đồn Bảo Đà, thành Quèn ở Đỗ Động không người chỉ huy chắc chắn sẽ có sở hở. Đêm mai chủ công, cùng tướng {p} dẫn quân quân vây thành, sau đó đốt lửa thật lớn. Thấy lửa chắc chắn Cảnh Thạc sẽ rút quân từ Bảo Đà về ứng cứu, tình hình ở Bảo Đà lẫn thành Quèn sẽ xảy ra hỗn loạn. Khi đó Đại vương quay đầu tấn công Cảnh Thạc, cùng lúc tướng Nguyễn Bặc và Lê Hoàn tấn công thẳng vào Bảo Đà, ép Cảnh Thạc vào giữa. Bị tấn công bất ngờ địch sẽ hoảng loạn, quân ta ắt sẽ thành công." }, new string[] { "06", "Được! Ta sẽ làm theo cách này. Đêm mai sẽ hành động, mọi người hãy chuẩn bị." } }, new string[][] { new string[] { "24", "Thành Quèn bị tấn công, ta phải về cứu ngay, các người hãy ở lại cố thủ." }, new string[] { "00", "Cảnh Thạc!! Ngươi đã hết đường chạy, muốn sống hãy mau chịu trói." }, new string[] { "24", "Hahaha, thật nực cười ! Chỉ một đám trẻ con mà dám cản đường ta ư? Có bản lĩnh thì hãy đến đây." } }, new string[][] { new string[] { "08", "Đại vương! Đỗ Động Giang đã lấy được, nhưng quân lực ta hao tổn khá nặng. Nếu đánh luôn Tây Phù Liệt thì rất khó, tốt nhất nên án binh bất động để cũng cố lực lượng. Mặt khác Đại vương nên đích thân đến Đằng Châu tiếp nhận binh lực của Phạm Bạch Hổ." }, new string[] { "06", "Ừm, Bạch Hổ đã có ý về đầu quân, ta cũng nên đến gặp trực tiếp ông ta. Có thêm binh lực của Đằng Châu thì việc diệt Nguyễn Siêu cũng không quá khó khăn. " }, new string[] { "08", "Đường xa nguy hiểm, người nên để Lê Hoàn tướng quân đi cùng." }, new string[] { "06", "Việc ở đây quân sư hãy cố sắp xếp." }, new string[] { "08", "Đại vương hãy yên tâm!" } }, new string[][] { new string[] { "07", "Không xong! Quân sư! Quân sư!! Nguyễn Siêu đã vây thành!" }, new string[] { "08", "Nguyễn Siêu đã đánh Đỗ Động sớm hơn ta dự tính. Binh lực và lương thảo hiện tại chỉ có thể cố thủ chờ viện binh từ Đằng Châu đến. Nguyễn Bặc hãy trấn thủ ở cửa Tây, cửa bắc mọi sự trông cậy vào {p} tướng quân. Năm ngày nữa quân viện binh sẽ đến, mọi người hãy cố gắng thủ thành." }, new string[] { "29", "Hôm nay bổn tướng đến đây, ngỡ có thể so kiếm với anh hùng, nào ngờ chỉ thấy lũ chuột chạy nháo nhào trong thành tìm chỗ trốn!" }, new string[] { "00", "Quân sư có biết người dưới kia là ai không?" }, new string[] { "08", "Nguyễn Trí Khả, tướng tiên phong của Nguyễn Siêu, dũng mãnh nhưng vô mưu. Tướng quân, hãy ráng nhẫn nhịn." }, new string[] { "29", "Lũ chuột nghe đây! Thời gian của bổn tướng quân có hạn, trong hôm nay nếu không ra khỏi hang, ta sẽ san bằng nơi này." }, new string[] { "00", "... ... ..." }, new string[] { "29", "Thật ngoan cố! Để xem lũ chuột các ngươi trốn được bao lâu?" }, new string[] { "00", "Địch tấn công, mọi người vào vị trí!" } }, new string[][] { new string[] { "07", "Âm mưu phá thành Đỗ Động thất bại, Nguyễn Siêu đã đắp thành cao hơn để phòng bị. Muốn tiến quân vào Tây Phù Liệt e rất khó, quân sư có cao kiến gì không?" }, new string[] { "08", "Tướng quân chớ lo! Nguyễn Siêu thận trọng phòng bị, như vậy trận chiến vừa rồi binh lực của hắn hao tổn khá nặng, hắn sẽ phải đích thân đi cầu cứu viện binh của 2 người anh Nguyễn Thủ Tiệp hoặc Nguyễn Khoan." }, new string[] { "09", "Vậy có nghĩa là Tây Phù Liệt như rắn mất đầu ?!" }, new string[] { "08", "Tướng quân nói rất phải! Đó chính là yếu điểm của Tây Phù Liệt, đêm mai quân ta nổi lửa đồng loạt đốt cửa Đông, cửa Tây, cửa Nam thì chắc binh lính sẽ hoảng loạn." }, new string[] { "07", "Được lắm! Ta sẽ hỏi tội chúng những ngày qua." }, new string[] { "08", "Trận này, nhất định phải lấy được thành. Mọi người tranh thủ nghỉ ngơi, đêm mai xuất binh." } }, new string[][] { new string[] { "00", "Trí Khả! Ta đến hỏi tội ngươi đây!" }, new string[] { "29", "Chỉ là con chuột nhắt, bổn tướng sẽ hóa kiếp cho ngươi!" }, new string[] { "00", "Tự tin thì cứ đến đây!!!" } }, new string[][] { new string[] { "00", "Nguyễn Siêu, chạy đâu cho thoát. Nạp mạng !!" }, new string[] { "28", "Muốn cản ta ư !? Mộng tưởng quá đấy !" } }, new string[][] { new string[] { "09", "Hay tin Nguyễn Siêu bị diệt. Nguyễn Khoan và Kiều Công Hãn đẵ liên kết, cùng trấn thủ ở vùng Tam Đái. Lý Khuê và Nguyễn Thủ Tiệp thì dựng tuyến phòng thủ ở Siêu Loại, xem ra ta gặp khó khăn lớn rồi." }, new string[] { "08", "Tướng quân đừng quá lo! Mối liên kết giữa Lý Khuê và Nguyễn Thủ Tiệp ngoài mặt nhìn rất chắc chắn, nhưng thực chất lại rất yếu. Hai người này từ lâu đã có mối hiềm khích với nhau, nên cắt đứt mối liên kết này không phải là khó." }, new string[] { "07", "Quân sư đã có cao kiến gì không?" }, new string[] { "08", "Cao kiến thì không, nhưng tôi có mẹo này. Năm ngày nữa 49 ngày mất của Nguyễn Siêu, chắc chắn Nguyễn Thủ Tiệp sẽ trở về Tiên Du. Cho một nhóm người trà trộn vào thành Siêu Loại, nửa đêm đốt cổng bắc. Bên ngoài ta giả làm quân của Thủ Tiệp tung cờ xí, nổi trống trận, đi từ hướng Tiên Du vào phá thành. Với tính đa nghi, Lý Khuê sẽ tưởng Thủ Tiệp còn nuôi thù cũ, lợi dụng đâm lén sau lưng. Nội chiến xảy ra, việc lấy thành Siêu Loại dễ như trở bàn tay." }, new string[] { "07", "Lưu quân sư, việc trà trộn hãy để tôi cùng các anh em trong doanh trại." }, new string[] { "08", "Việc này rất nguy hiểm..." }, new string[] { "07", "Quân sư hãy yên tâm, tôi có thể lo liệu được." }, new string[] { "08", "Tướng quân hãy cầm theo bí kíp này, nếu gặp nguy hãy mở ra." }, new string[] { "08", "Giờ mọi người về nghỉ. Sáng mai, chúng ta sẽ về Tế Giang hội ngộ với Vạn Thắng Vương. Lưu cơ có việc phải làm ở Đỗ Động, tôi sẽ đến sau. " }, new string[] { null, "Quân sư, xin cáo lui." }, new string[] { "08", "{p} tướng quân xin dừng bước, tôi có chuyện cần bàn với tướng quân!" }, new string[] { "00", "Xin quân sư cứ nói!" }, new string[] { "08", "Tôi nghe nói, ở vùng Đỗ Động có đám người tự xưng là con cháu Ngô tiên chúa đã khởi binh tiến đánh Hoa Lư, nhưng khi đến Ô Man thì đụng độ với hào trưởng làng ấy là Ngô Phó. Đám người này không diệt sau này sẽ rắc rối, tướng quân hãy cùng tôi đến giúp Ngô Phó một tay. Ngài hãy về chuẩn bị, sớm mai ta sẽ lên đường. " }, new string[] { "00", "Mạt tướng xin cáo lui!" } }, new string[][] { new string[] { "00", "Ngô hào trưởng, quân của Vạn Thắng Vương xin đến giúp một tay!" }, new string[] { "15", "Thật tốt quá! Quân địch rất hung hãn, tướng quân hãy cẩn trọng!" } }, new string[][] { new string[] { "08", "Thưa Đại vương, việc ở Tây Phù Liệt tôi đã sắp xếp xong." }, new string[] { "06", "Quân sư, Nguyễn Thủ Tiệp đã về Tiên Du. Khi nào ta sẽ đánh vào Siêu Loại?" }, new string[] { "08", "Theo thuộc hạ tính thì đêm mai có gió lớn, nội gián của ta sẽ đốt doanh trại địch, khi đó lửa lan rất nhanh. Thấy lửa, địch sẽ náo loạn, lúc đó ta xuất binh đánh vào Siêu Loại" }, new string[] { "06", "Được, đêm mai ta sẽ lấy Siêu Loại. Mọi người hãy về chuẩn bị." }, new string[] { null, "Tuân lệnh Đại vương!" } }, new string[][] { new string[] { "31", "Báo! Báo! Nguyễn Thủ Tiệp đã trở mặt, hắn đang phá cổng bắc." }, new string[] { "30", "Grr...grr...Con cáo già! Giết, giết hết bọn chúng cho ta!!" }, new string[] { "31", "Báoooo!!! Cổng nam, quân của Đinh Bộ Lĩnh đã đánh vào!" }, new string[] { "30", "Nguy rồi !! Mau mau...." } }, new string[][] { new string[] { "00", "Lý Khuê ở đằng kia! Mau đuổi theo." }, new string[] { "30", "Mau! Mau chạy vào làng." }, new string[] { "00", "Chạy đâu cho thoát!" } }, new string[][] { new string[] { "08", "Thất bại ở Siêu Loại, binh lực của Nguyễn Thủ Tiệp đã mất hơn nữa, quân lính gần như mất hết nhuệ khí. Đây là thời cơ thuận lợi cho ta đánh Tiên Du. Đại vương, hãy cho xuất binh." }, new string[] { "06", "Nguyễn Bặc, ông dẫn quân đánh vào cánh trái Tiên Du. Lê Hoàn thì đánh vào cánh phải. Ta cùng các tướng khác tấn công trực diện. Mọi người, tiến thẳng Tiên Du!" }, new string[] { null, "Thuộc hạ tuân lệnh!" } }, new string[][] { new string[] { "31", "Báoooo! quân ta đã thất thủ." }, new string[] { "32", "Mau, mau theo ta chạy vào núi." }, new string[] { "00", "Ác tặc, chạy đâu cho thoát!!" } }, new string[][] { new string[] { "07", "Hừ, không ngờ tên phản tặc Lã Xử Bình gửi thư cầu cứu liên quân Nguyễn Khoan và Kiều Công Hãn, 7 ngày nữa liên quân sẽ đến Cổ Loa." }, new string[] { "06", "Nếu liên quân hợp sức với Lữ Xử Bình, ta sẽ khó tiến vào Cổ Loa. Quân sư, ông có kế sách gì không?" }, new string[] { "08", "Hiện tại quân lực ở Cổ Loa còn yếu. Trong 5 ngày, phải đánh vào Cổ Loa trước khi liên quân đến. Nếu không quân ta không còn cơ hội nào khác." }, new string[] { "06", "{p}, Nguyễn Bặc, Lê Hoàn đi tiên phong, cấp tốc đến Cổ Loa. Mọi người hãy cố gắng!" }, new string[] { null, "Tuân lệnh Đại vương!" } }, new string[][] { new string[] { "35", "Địch đã tấn công. Chủ công, hãy ra lệnh!" }, new string[] { "34", "Hãy ráng cầm cự chờ liên quân đến. Cung thủ, bắn tên!" } }, new string[][] { new string[] { "35", "Chủ công, quân ta đã thất thủ..." }, new string[] { "34", "Grrr....Mau, rút về Tam Đái." }, new string[] { "00", "Lữ Xử Bình, ngươi hết đường rồi! Sáaatttt" } }, new string[][] { new string[] { "06", "Biết quân ta đã chiếm Cổ Loa, liên quân rút về cố thủ ở Tam Đái. Bây giờ đánh từ Cổ Loa vào Tam Đái rất khó, mọi người có kế sách gì không? " }, new string[] { "08", "Nếu Tam Đái đánh khó thì ta sẽ đánh Phong Châu trước." }, new string[] { "06", "Phong Châu?" }, new string[] { "08", "Kiều Công Hãn đem quân xuống Tam Đái, chắc chắn Phong Châu sẽ sơ hở. Ta cho 2 đạo quân tiến từ 2 hướng Đường Lâm và Cổ Loa đánh vào Tam Đái. Mặt khác cho đạo quân khác đi vòng đường núi đánh Phong Châu, Kiều Công Hãn chắc chắn rút quân về. Lúc đó chỉ còn mình Nguyễn Khoan ở Tam Đái, ta sẽ đánh vào được." }, new string[] { "06", "Nguyễn Bặc, {p} tướng quân hãy đem quân đến Đường Lâm, Lê Hoàn dẫn quân đến Phong Châu, các tướng còn lại hãy theo ta đánh thẳng từ Cổ Loa đến. Mọi người về nghỉ ngơi, sớm mai ta sẽ xuất quân!" }, new string[] { null, "Tuân lệnh Đại vương!" } }, null, new string[][] { new string[] { "39", "Báoooo!! Thưa chủ công, Phong Châu bị tấn công!" }, new string[] { "38", "Mau! Về hỗ trợ Phong Châu." }, new string[] { "39", "Báoooo!! Tướng giặc Lê Hoàn đã chiếm Phong Châu!" }, new string[] { "38", "Grr..grr...Ta đã quá sơ ý! Lui về Hồi Hồ tạm lánh một thời gian." }, new string[] { "38", "Đinh Bộ Lĩnh! Ta thề sẽ lấy lại Phong Châu." }, new string[] { "00", "Nguyễn Khoan, có gan ra đây so cao thấp với ta!" }, new string[] { "36", "Ngông cuồng! Hôm nay ta sẽ lấy đầu bọn bay để trả thù của Nguyễn Siêu và Thủ Tiệp." } }, new string[][] { new string[] { "08", "Đại vương, hạ tướng cũ của Trần lão công đã làm phản, hắn đem quân đánh vào Kỳ Bố. Mọi người trong thành đang cố thủ, lương thực chỉ đủ dùng trong vài ngày, ta phải đem quân đến giải vây ngay!" }, new string[] { "06", "{p} tướng quân, khanh hãy đem quân trở về ứng cứu Kỳ Bố. Nhưng người còn lại theo ta đánh vào Phong Châu." }, new string[] { "00", "Tuân lệnh Đại vương!" } }, new string[][] { new string[] { "00", "Phản tặc, có ta đến đây, hãy mau chịu tội!" }, new string[] { "33", "Sức ngươi còn kém lắm, chưa đủ đâu!" }, new string[] { "00", "Chớ ngông cuồng! Hãy xem đây !!!" } }, new string[][] { new string[] { "06", "Thất bại ở Phong Châu và Tam Đái, Kiều Công Hãn đã rút quân thẳng về Hồi Hồ nương nhờ em hắn là Kiều Thuận. Địa hình ở đó hiểm trở, rất khó tấn công, quân sư có kế sách gì không?" }, new string[] { "08", "Thưa Đại Vương, thực ra địa hình hiểm trở chính là yếu điểm của Hồi Hồ!" }, new string[] { "06", "Yếu điểm!? Ta chưa hiểu, quân sư hãy nói rõ." }, new string[] { "08", "Thành Hồi Hồ xung quanh là vùng đồi núi hiểm trở, ta không nên tấn công, chia quân ra đóng ở  nơi hiểm yếu ngăn chặn nguồn nước. Vây phục ba ngày, tự chúng sẽ mò ra, lúc ấy ta sẽ diệt được." }, new string[] { "06", "Quân sư nói phải lắm, 12 sứ quân nay chỉ còn anh em họ Kiều, ta cũng không cần phải vội. Chúng ta hãy theo kế của quân sư." }, new string[] { "00", "Tuân lệnh đại vương!" } }, null, new string[][] { new string[] { "40", "Huynh trưởng, lương thực trong thành chẳng còn bao nhiêu. Nếu tiếp tục ở trong thành e rằng sẽ không qua khỏi." }, new string[] { "38", "Với tình thế này, nên tìm cách thoát thân trước." }, new string[] { "40", "Địch đã bao vây 4 hướng, ta chạy đi đâu bây giờ." }, new string[] { "38", "Ở cửa Bắc, lực lượng của địch yếu nhất. Nếu phá được vòng vây, thì chạy lên phương Bắc xin nhà Tống cứu viện." }, new string[] { "40", "Đệ sẽ chọn ra 1 đám quân tinh nhuệ, đêm nay chúng ta phá vòng vây." }, new string[] { "00", "Kiều tặc, chạy đâu cho thoát!" } }, null, new string[][] { new string[] { "08", "Thưa đại vương, loạn 12 sứ quân đã dẹp xong, bây giờ đã đến lúc xưng đế." }, new string[] { "06", "Ta đang suy nghĩ, không biết chọn nơi nào làm kinh đô. Quân sư có cao kiến gì không?" }, new string[] { "08", "Người Hoa Lư nên chọn Hoa Lư làm gốc, hơn nữa Hoa Lư là nơi núi non trùng điệp. Núi trong sông, sông trong núi. Căn cứ thủy bộ thuận tiện, sau lưng là rừng, trước mặt là đồng bằng, xa nữa là biển cả. Nơi đây non sông thì tráng lệ, phong thủy hài hòa nên Ấu Rồng thường xuất hiện gây nhiều khó khăn cho bá tánh." }, new string[] { "06", "Vậy ta diệt Ấu Rồng trước, sau dựng kinh đô. Mọi người về nghỉ ngơi, sớm mai trở về Hoa Lư." }, new string[] { null, "Tuân lệnh đại vương." } }, null, new string[][] { new string[] { "06", "Ta, một người nhỏ bé, nhờ hưng binh mà dẹp loạn, thống nhất đất nước. Nay thuận ý muôn dân, ta xưng hiệu Đinh Tiên Hoàng đế, đặt quốc hiệu là Đại Cồ Việt." }, new string[] { null, "Đinh Tiên Hoàng vạn tuế vạn tuế!" } } };
            C_ea.f_c = new string[][][] { new string[][] { new string[] { "08", "Tướng quân rất thông minh, những gì tôi truyền đạt ngài tiếp nhận khá nhanh." }, new string[] { "00", "Chỉ là chút tài mọn, quân sư đã quá khen!" } }, null, null, null, new string[][] { new string[] { "00", "Sơn tặc đã diệt xong. Doanh trại rất thích hợp làm Đấu Trường luyện tập cho quân ta. Các ngươi hãy ở lại canh giữ, còn lại mau theo ta trở về Hoa Lư." } }, null, null, null, new string[][] { new string[] { "22", "Giặc quá mạnh, ta thua rồi. Mau mở cửa thành...đầu hàng" } }, null, new string[][] { new string[] { "00", "Nhật Khánh, bây giờ ngươi muốn sống hay muốn chết?" }, new string[] { "27", "Họ Ngô ta đã dựng nên đất nước, chẳng may gặp kẻ gian thần hãm hại mà mất nước. Ta nuôi chí khôi phục cơ nghiệp tiên chúa, nghiệp lớn không thành, muốn chém thì chém, chớ nhiều lời !!!" }, new string[] { "00", "Được, ta sẽ cho ngươi toại nguyện." }, new string[] { "08", "Tướng quân dừng tay!!!" }, new string[] { "08", "Lưu Cơ đến muộn, mong Ngô công tử bỏ qua. Tiên phụ công tử với Vạn Thắng Vương là bạn từ thời tóc còn để chỏm, chiến tranh loạn lạc 2 người đi 2 hướng khác nhau. Hay biết công tử là con cố nhân, nay người muốn gặp công tử ở Hoa Lư. Xin mời công tử lên xe ngựa." }, new string[] { "27", "Hmm ... ... ..." } }, null, new string[][] { new string[] { "20", "Rút quân !!!!" }, new string[] { "00", "Đừng đuổi theo! Hãy lui vào thành." } }, null, null, new string[][] { new string[] { "00", "Lã Đường đã chết!! Kẻ nào đầu hàng sẽ được tha." } }, null, null, new string[][] { new string[] { "00", "Thắng thua đã rõ. Trói hắn lại." }, new string[] { "24", "Muốn bắt ta ư? Còn lâu.....Yaaaa........hự....hự... !!" }, new string[] { "00", "Hắn đã tự sát, hãy mau lấy thành." } }, null, new string[][] { new string[] { "00", "Viện binh đã đến, mọi người phản công !!!" }, new string[] { "29", "Không xong rồi! Hãy mau rút về tiền đồn chờ lệnh Hữu công Nguyễn Siêu." } }, null, new string[][] { new string[] { "00", "Trí Khả đã bị diệt, hãy mau tìm Nguyễn Siêu!" }, new string[] { "08", "Nguyễn Siêu đã chạy hướng Đông Phù Liệt sang Tiên Du, tướng quân hãy mau đuổi theo, đừng để hắn qua sông!" } }, new string[][] { new string[] { "00", "Thủ cấp của Nguyễn Siêu trong tay ta, muốn sống thì mau buông vũ khí đầu hàng! " } }, null, new string[][] { new string[] { "15", "Đa tạ tướng quân đã trợ giúp!" }, new string[] { "00", "Ngô hào trưởng, đừng khách sáo. Đây là nhiệm vụ của tôi. Phản loạn đã diệt xong, nay tôi phải về Tế Giang để giúp Vạn Thắng Vương. Ngô hào trưởng, hẹn ngày tái ngộ!" }, new string[] { "15", "Tướng quân, bảo trọng!" } }, null, new string[][] { new string[] { "00", "Nói !! Muốn sống thì cho ta biết Lý Khuê đang ở đâu !?" }, new string[] { "31", "Lý sứ quân đã chạy về hướng Dương Xá, xin tướng quân tha mạng." }, new string[] { "00", "Nhốt tên này lại, chờ ta về xử lý. Những người còn lại mau đuổi theo Lý Khuê!" } }, new string[][] { new string[] { "00", "Chém! Đem đầu Lý Khuê về." } }, null, new string[][] { new string[] { "00", "Còn kẻ nào chán sống thì hãy bước lên !" } }, null, null, new string[][] { new string[] { "34", "Á.....! Chết ta......" } }, null, null, new string[][] { new string[] { "00", "Nguyễn Khoan đã bỏ mạng. Kẻ nào đầu hàng sẽ được tha chết!" } }, null, new string[][] { new string[] { "00", "Phản tặc đã diệt, hãy mau đến Phong Châu." } }, null, null, null, new string[][] { new string[] { "00", "Anh em họ Kiều đã diệt xong, mau báo cho Vạn Thắng Vương." } }, null, null, null };
            C_ea.f_d = new string[][][] { null, null, null, null, new string[][] { new string[] { "42", "Không cho chúng chạy! Đuổi theo giết sạch, không chừa một mống." } }, null, null, null, new string[][] { new string[] { "22", "Thực lực quá kém, đúng là không biết trời cao." } }, null, new string[][] { new string[] { "27", "Chết nè !!!" }, new string[] { "00", "A....a....a......" } }, null, new string[][] { new string[] { "20", "Chống đối ta chỉ có chết, hãy nhìn đó mà làm gương." } }, null, null, new string[][] { new string[] { "08", "Áaaaaa ... a.......a......." }, new string[] { "08", "{p} tướng quân đã bại trận. Rút quân!!!" } }, null, null, new string[][] { new string[] { "24", "Tiến lên!! Ai bắt được Đinh Bộ Lĩnh dù sống hay đã chết sẽ được phong quan." } }, null, new string[][] { new string[] { "00", "Thành đã thất thủ, mọi người mau rút về Hoa Lư, ta sẽ ở lại cản đường. Mau!! Không được chần chừ. Vạn Thắng Vương, xin thứ lỗi cho thuộc hạ." } }, null, new string[][] { new string[] { "29", "Còn tên nào muốn được hóa kiếp thì bước lên !" } }, new string[][] { new string[] { "28", "Hừm, làm mất thời gian!" } }, null, new string[][] { new string[] { "15", "{p} tướng quân đã bại trận!! Rút quân." } }, null, new string[][] { new string[] { "30", "Tướng giặc đã chết! Đuổi theo giết sạch bọn chúng." } }, new string[][] { new string[] { "30", "Chỉ có bấy nhiêu mà cũng dám cản đường ta sao !?" } }, new string[][] { new string[] { "32", "Sức chỉ thế mà đòi lấy đầu ta ư !?" } }, null, null, new string[][] { new string[] { "34", "Mau ra khỏi thành!" } }, null, null, new string[][] { new string[] { "36", "Siêu, Tiệp! Ta đã báo thù cho hai đệ." } }, null, new string[][] { new string[] { "33", "Muốn cản ta ư? Chưa đủ sức!" } }, null, null, null, new string[][] { new string[] { "40", "Qua ngọn núi phía trước ta sẽ an toàn. Đinh Bộ Lĩnh hãy chờ đó, nhất định ta sẽ quay về lấy lại tất cả." } }, null, null, null, null };
            C_ea.f_e = new string[][][] { new string[][] { new string[] { null, "Giúp chúng tôi với !!!" }, new string[] { "06", "Sơn trang phía trước bị yêu quái tấn công, tướng quân hãy mau đến giúp!" }, new string[] { "00", "Tuân lệnh đại vương!" } }, new string[][] { new string[] { "07", "Các ngươi là ai? Sao dám cản đường !" }, new string[] { "09", "Thưa tướng quân! Tiểu dân xin gặp Vạn Thắng Vương." }, new string[] { "06", "Ngươi là ai?  Gặp ta có việc gì ?" }, new string[] { "09", "Thưa đại vương, tiểu dân họ Lê tên Hoàn, người ở Bảo Thái, từ lâu đã nghe danh đức của đại vương, nên muốn phò giúp." }, new string[] { "06", "Hãy đến Hoa Lư, chờ ta đánh trận về rồi tính." }, new string[] { "09", "Tiểu dân chờ người rất lâu rồi, hãy cho tôi một cơ hội." }, new string[] { "06", "Vậy ngươi hãy thử đấu với {p} xem sao." } }, new string[][] { new string[] { "12", "Mô phật! Bần tăng tiếp đón chậm trễ, Lưu tiên sinh hãy lượng thứ." }, new string[] { "08", "Đại sư đừng khách sáo! Hôm nay tôi đến đây có việc cần ngài giúp đỡ. " }, new string[] { "12", "Lưu quân sư, nếu giúp được bần tăng sẽ cố hết sức." }, new string[] { "08", "Không dấu gì đại sư, binh lực của Vạn Thắng Vương tuy uy dũng nhưng vẫn còn thiếu người chỉ dẫn. Đại sư, xin hãy giúp một tay." }, new string[] { "12", "Việc này hơi khó cho bần tăng vì chùa có quy định nếu thỉnh sư xuống núi phải phá được La Hán Trận. Trước nay chưa có ai phá được trận này, Lưu tiên sinh e rằng tôi khó mà giúp ông." }, new string[] { "08", "........" }, new string[] { "00", "Lưu tiên sinh, hãy để tiểu tướng thử phá La Hán Trận" }, new string[] { "08", "Tướng quân, hãy trận trọng." } }, new string[][] { new string[] { "14", "Các ngươi là ai, hãy mau tránh đường cho ta." }, new string[] { "00", "Láo xược, tiếp chiêu!" } }, new string[][] { new string[] { "13", "Chẳng hay tướng quân ghé đến tệ xá có việc cần gì chỉ bảo?" }, new string[] { "00", "Ta đi lạc đến đây, xin hỏi cao danh quý tánh của tiên sinh." }, new string[] { "13", "Tại